BEGIN;
DO $$
DECLARE admin_user_id bigint; sam_organization_id bigint; property_listing_id bigint;
BEGIN
PERFORM pg_advisory_xact_lock(hashtext('sam-import-5503'));
IF EXISTS (SELECT 1 FROM listing_sources WHERE upper(reference_code)='1T2428' OR source_url ~ '[?&]id=5503(&|$)') OR EXISTS (SELECT 1 FROM listings WHERE public_listing_id='78931428-00ac-4ecb-9250-d38108825503' OR slug='sam-bigland-factory-land-162-plots-1t2428' OR (abs(latitude-14.113005)<0.0001 AND abs(longitude-100.606142)<0.0001 AND abs(land_area_sqm-50498.8)<1)) THEN RAISE NOTICE 'SAM 1T2428 exists; skipping'; RETURN; END IF;
SELECT id INTO admin_user_id FROM auth_users WHERE lower(email)='mapxprop@gmail.com' AND deleted_at IS NULL ORDER BY id LIMIT 1;
SELECT id INTO sam_organization_id FROM organizations WHERE slug='sukhumvit-asset-management-sam' AND verification_status='verified' AND is_active=true AND deleted_at IS NULL ORDER BY id LIMIT 1;
IF admin_user_id IS NULL OR sam_organization_id IS NULL THEN RAISE EXCEPTION 'Existing admin and verified SAM organization required'; END IF;
INSERT INTO public.listings (public_listing_id, user_id, organization_id, created_by_user_id, published_by_user_id, property_type_code, usage_type, listing_type, listing_scope, custom_project_name, title, description, sale_price, price_negotiable, land_area_sqm, contact_name, contact_phone, contact_email, line_id, show_phone, show_email, address_line1, address_line2, road, latitude, longitude, province_name, district_name, subdistrict_name, listing_status, moderation_status, approved_at, published_at, moderation_submitted_at, moderated_at, is_verified, is_active, source_channel, price_unit, slug) VALUES ('78931428-00ac-4ecb-9250-d38108825503', admin_user_id, sam_organization_id, admin_user_id, admin_user_id, 'land', 'business', 'sale', 'whole_property', 'บิ๊กแลนด์ แฟคตอรี่', 'ที่ดินบิ๊กแลนด์ แฟคตอรี่ คลองหลวง 162 แปลง รวม 31 ไร่ 2 งาน 24.7 ตร.ว.', 'รายละเอียดทรัพย์

ที่ดินเปล่าภายในโครงการบิ๊กแลนด์ แฟคตอรี่ ตำบลคลองหนึ่ง อำเภอคลองหลวง จังหวัดปทุมธานี เข้าจากถนนพหลโยธิน (ทล.1) ผ่านซอยสามารถ รวม 162 แปลง เนื้อที่ 31 ไร่ 2 งาน 24.7 ตร.ว. หรือ 12,624.7 ตร.ว. (50,498.8 ตร.ม.) ราคาประกาศขาย SAM 286,987,000 บาท รหัส 1T2428 ต้นทางแสดงราคาประมาณ 22,732 บาท/ตร.ว. ใช้ราคารวมเป็นหลัก

ลักษณะที่ดิน

เป็นแปลงย่อยรูปสี่เหลี่ยมผืนผ้า ไม่ใช่ที่ดินผืนเดียวติดต่อกันทั้งหมด เนื่องจากมีถนนภายในโครงการคั่นระหว่างแปลง ขนาดแต่ละแปลงตั้งแต่ 23.7 ถึง 198 ตร.ว. โฉนดเลขที่ 85464–85550, 85627–85662, 85664–85680 และ 85749–85770 รวม 162 ฉบับ SAM ระบุผังเมืองสีม่วง ควรตรวจข้อกำหนดการใช้ประโยชน์ให้ตรงกับกิจการที่จะดำเนินการ

ข้อควรทราบเกี่ยวกับทรัพย์

โฉนดเลขที่ 85770 เนื้อที่ 25 ตร.ว. ซึ่งรวมอยู่ในเนื้อที่ทั้งหมด ถูกจัดสรรไว้เป็นสาธารณูปโภคภายในโครงการประเภทบ่อบาดาล จึงไม่ควรนับเป็นพื้นที่พัฒนาได้โดยไม่มีข้อจำกัด

ทางเข้าซอยสามารถเป็นถนนส่วนบุคคลบนโฉนดเลขที่ 355 โดย SAM ระบุว่าจดภาระจำยอมให้แปลงทรัพย์แล้ว ผิวคอนกรีตกว้างประมาณ 16 เมตร เขตทางประมาณ 30 เมตร ส่วนถนนภายในโครงการมีเขตทางประมาณ 10 และ 14 เมตร แต่ต้นทางระบุว่าไม่มีสภาพทาง ผู้สนใจควรตรวจตำแหน่งแปลง สิทธิในการใช้ทางและสภาพการเข้าถึงแต่ละแปลงก่อนเสนอซื้อ

SAM มีทรัพย์รหัส 1T2831, 1T2833 และ 1T2834 ภายในโครงการเดียวกันด้วย ผังรวมแสดงหลายรหัส ประกาศนี้เฉพาะรหัส 1T2428 ไม่รวมที่ดินของรหัสอื่น

ทำเลและการเดินทาง

อยู่ในย่านที่อยู่อาศัย พาณิชยกรรมและอุตสาหกรรม สถานที่ใกล้เคียงตาม SAM ได้แก่ นิคมอุตสาหกรรมนวนคร โลตัส บิ๊กซีนวนคร โรงพยาบาลนวนคร ตลาดไทและมหาวิทยาลัยธรรมศาสตร์ จากรังสิตมุ่งหน้าวังน้อยบนถนนพหลโยธิน ถึงโชว์รูมโตโยต้า เฟรนส์ชิบช่วง กม.45–46 เลี้ยวซ้ายเข้าซอยสามารถประมาณ 400 เมตร ทรัพย์อยู่ภายในโครงการด้านซ้ายมือ

ภาพและข้อมูลต้นทาง

รูปจริงและผังจาก SAM รวม 10 ภาพหลังตัดรูปซ้ำ ภาพภาคสนามหลายภาพแสดงวันที่ 30 พฤษภาคม 2565 ควรตรวจสภาพปัจจุบัน พิกัด 14.113005, 100.606142 ดึงจากลิงก์นำทาง SAM และตรงกับลิงก์แผนที่ เป็นจุดอ้างอิงของกลุ่มทรัพย์ ไม่ใช่พิกัดขอบเขตของทุกแปลง

ราคาและสถานะซื้อตรงตรวจจากหน้า SAM วันที่ 15 กันยายน 2569 ติดต่อ SAM โทร 02-686-1888 อีเมล sales@sam.or.th หรือ LINE @samline แจ้งรหัส 1T2428 เพื่อยืนยันรายการโฉนด ราคา สถานะพร้อมขาย การนัดชมและเงื่อนไขล่าสุด', 286987000, false, 50498.8, 'ฝ่ายขายและส่งเสริมกิจกรรมการขาย — SAM', '026861888', 'sales@sam.or.th', '@samline', true, true, 'โครงการบิ๊กแลนด์ แฟคตอรี่ ซอยสามารถ', 'เข้าจากถนนพหลโยธินประมาณ 400 เมตร', 'ซอยสามารถ ถนนพหลโยธิน (ทล.1)', 14.113005, 100.606142, 'ปทุมธานี', 'คลองหลวง', 'คลองหนึ่ง', 'active', 'approved', now(), now(), now(), now(), true, true, 'editorial_import', 'total', 'sam-bigland-factory-land-162-plots-1t2428') RETURNING id INTO property_listing_id;
