INSERT INTO public.listing_translations (listing_id, language_code, title, description, address_line1, address_line2, road, subdistrict_name, district_name, province_name, seo_title, seo_description, translation_status, translation_source, reviewed_at, search_text) VALUES (property_listing_id, 'en', 'Bigland Factory Land, Khlong Luang — 162 Plots, THB286.987M', 'Vacant land in Bigland Factory, Khlong Nueng, Khlong Luang, Pathum Thani, accessed from Phahonyothin Highway 1 via Soi Samat. The 162 plots total 31 rai 2 ngan 24.7 sq.wah, or 12,624.7 sq.wah (50,498.8 sq.m.). SAM announced price THB286,987,000, asset1T2428. Source unit price is approximately THB22,732/sq.wah; the total price governs.

These are separate rectangular subplots divided by internal project roads, not one continuous site. Individual plots range from 23.7 to198 sq.wah. Chanote ranges85464–85550,85627–85662,85664–85680,85749–85770 total162 certificates. SAM reports purple zoning; verify permitted use for the intended activity.

Material restrictions: deed85770,25 sq.wah included in the total, was allocated as a project public-utility groundwater-well plot. Do not treat it as unrestricted development land. Soi Samat is private road deed355; SAM reports a registered easement benefiting the property, approximately16m concrete carriageway and30m right of way. Internal project rights of way are10m and14m, but SAM says they have no formed road condition. Verify each plot''s access, rights and boundaries before offering.

Other SAM assets1T2831,1T2833 and1T2834 appear in the same project/master plan; this listing includes only1T2428.

Residential, commercial and industrial surroundings near Nava Nakorn Industrial Estate, Lotus''s, Big C Nava Nakorn, Nava Nakorn Hospital, Talad Thai and Thammasat University. From Rangsit toward Wang Noi on Phahonyothin, at Toyota Friendship around km45–46 turn left into Soi Samat for400m; the plots are within the project on the left.

